        // Services SEO Text
        servicesSeoTitle: 'Професійна веб-розробка для вашого бізнесу',
        servicesSeoText1: 'Web Impuls — це команда досвідчених розробників та дизайнерів, яка спеціалізується на створенні сучасних веб-рішень для бізнесу будь-якого масштабу. Ми працюємо з клієнтами з України, Польщі, Німеччини та інших країн Європи, надаючи послуги найвищої якості за конкурентними цінами. Наш підхід базується на глибокому розумінні потреб кожного клієнта та використанні найсучасніших технологій веб-розробки.',
        servicesSeoText2: 'Кожен проект для нас — це унікальна можливість створити щось особливе. Ми не використовуємо шаблонні рішення, а розробляємо індивідуальний дизайн та функціонал, який точно відповідає цілям вашого бізнесу. Від простих лендінгів до складних веб-додатків з інтеграцією платіжних систем, CRM та аналітики — ми маємо досвід у реалізації проектів різної складності.',
        servicesSeoHeading1: 'Чому обирають Web Impuls?',
        servicesSeoText3: 'Ми працюємо виключно з сучасними технологіями: Next.js 15, React 19, TypeScript, Tailwind CSS та Prisma ORM. Це забезпечує високу швидкість завантаження сайтів, відмінну SEO-оптимізацію та легкість подальшої підтримки. Наші сайти отримують високі оцінки Google PageSpeed Insights, що напряму впливає на конверсію та позиції в пошуковій видачі. Крім того, ми надаємо повний супровід проекту — від консультації до запуску та подальшої технічної підтримки.',
        servicesSeoHeading2: 'Повний цикл розробки',
        servicesSeoText4: 'Наші послуги охоплюють весь цикл створення веб-продукту: аналіз бізнес-вимог, проектування UX/UI дизайну, frontend та backend розробка, тестування, деплой та подальша підтримка. Ми працюємо за методологією Agile, що дозволяє вам бачити прогрес на кожному етапі та вносити корективи в процесі розробки. Прозора комунікація та регулярні демонстрації — наш стандарт роботи.',
        servicesSeoHeading3: 'Гарантія якості та підтримка',
        servicesSeoText5: 'Після запуску проекту ми не залишаємо вас наодинці. Кожен клієнт отримує гарантійний період безкоштовного виправлення помилок, а також можливість підключити пакет технічної підтримки. Ми проводимо навчання по роботі з адмін-панеллю, надаємо детальну документацію та завжди готові відповісти на ваші запитання. Наша мета — довгострокове партнерство, тому ми зацікавлені в успіху вашого проекту.',
        servicesSeoConclusion: 'Готові обговорити ваш проект? Зв\'яжіться з нами для безкоштовної консультації. Ми проаналізуємо ваші потреби, запропонуємо оптимальне рішення та надамо детальну оцінку термінів і вартості розробки.',
