        pricingSeoText1: 'Вартість створення веб-сайту — це не фіксована цифра, а результат детального аналізу потреб вашого бізнесу. Кожен проект унікальний, тому ми підходимо до ціноутворення індивідуально, враховуючи специфіку галузі, цільову аудиторію та бізнес-цілі клієнта. У Web Impuls ми прагнемо забезпечити максимальну прозорість: ви завжди знатимете, за що платите і який результат отримаєте.',
        pricingSeoText2: 'Наші ціни на розробку сайтів у Європі конкурентні та відповідають якості, яку ми надаємо. Ми працюємо з клієнтами з Польщі, Німеччини, Великобританії та інших країн ЄС, пропонуючи сучасні технологічні рішення на базі Next.js, React та TypeScript. Це означає швидкі, SEO-оптимізовані сайти, які добре ранжуються в Google та забезпечують високу конверсію.',
        pricingSeoHeading1: 'Що впливає на вартість веб-розробки?',
        pricingSeoText3: 'Основні фактори, що визначають ціну: складність дизайну (шаблонний чи унікальний), кількість сторінок та розділів, необхідна функціональність (форми, особисті кабінети, платіжні системи, CRM-інтеграції), а також терміни виконання. Наприклад, проста landing page з адаптивним дизайном та базовою SEO-оптимізацією коштуватиме значно менше, ніж повноцінний інтернет-магазин з каталогом товарів, кошиком, інтеграцією з платіжними шлюзами Stripe чи LiqPay та системою управління замовленнями.',
        pricingSeoHeading2: 'Чому варто інвестувати в якісний сайт?',
        pricingSeoText4: 'Професійний веб-сайт — це не витрата, а інвестиція в розвиток бізнесу. Якісно розроблений сайт працює на вас 24/7: залучає клієнтів через органічний пошук, формує довіру до бренду, автоматизує продажі та комунікацію. Ми використовуємо найновіші технології веб-розробки: серверний рендеринг для швидкості завантаження, оптимізацію Core Web Vitals для кращих позицій у Google, адаптивний дизайн для всіх пристроїв та accessibility стандарти для доступності.',
        pricingSeoHeading3: 'Прозоре ціноутворення без прихованих платежів',
