        viewPricing: 'Zobacz ceny',
        // Services SEO Text
        servicesSeoTitle: 'Profesjonalne tworzenie stron internetowych dla Twojej firmy',
        servicesSeoText1: 'Web Impuls to zespół doświadczonych programistów i projektantów specjalizujących się w tworzeniu nowoczesnych rozwiązań internetowych dla firm każdej wielkości. Współpracujemy z klientami z Ukrainy, Polski, Niemiec i innych krajów europejskich, oferując usługi najwyższej jakości w konkurencyjnych cenach. Nasze podejście opiera się na głębokim zrozumieniu potrzeb każdego klienta i wykorzystaniu najnowocześniejszych technologii web developmentu.',
        servicesSeoText2: 'Każdy projekt to dla nas wyjątkowa okazja do stworzenia czegoś szczególnego. Nie korzystamy z szablonowych rozwiązań — projektujemy indywidualny design i funkcjonalność, które dokładnie odpowiadają celom Twojego biznesu. Od prostych landing page\'ów po złożone aplikacje webowe z integracją systemów płatności, CRM i analityki — mamy doświadczenie w realizacji projektów o różnym stopniu złożoności.',
        servicesSeoHeading1: 'Dlaczego wybierają Web Impuls?',
        servicesSeoText3: 'Pracujemy wyłącznie z nowoczesnymi technologiami: Next.js 15, React 19, TypeScript, Tailwind CSS i Prisma ORM. Zapewnia to wysoką szybkość ładowania stron, doskonałą optymalizację SEO i łatwość dalszego wsparcia. Nasze strony otrzymują wysokie oceny Google PageSpeed Insights, co bezpośrednio wpływa na konwersję i pozycje w wynikach wyszukiwania. Ponadto zapewniamy pełne wsparcie projektu — od konsultacji po wdrożenie i dalsze wsparcie techniczne.',
        servicesSeoHeading2: 'Pełny cykl rozwoju',
        servicesSeoText4: 'Nasze usługi obejmują cały cykl tworzenia produktu webowego: analiza wymagań biznesowych, projektowanie UX/UI, rozwój frontend i backend, testowanie, deployment i dalsze wsparcie. Pracujemy według metodologii Agile, co pozwala śledzić postępy na każdym etapie i wprowadzać korekty w trakcie rozwoju. Przejrzysta komunikacja i regularne demonstracje — to nasz standard pracy.',
        servicesSeoHeading3: 'Gwarancja jakości i wsparcie',
        servicesSeoText5: 'Po uruchomieniu projektu nie zostawiamy Cię samego. Każdy klient otrzymuje okres gwarancyjny bezpłatnego naprawiania błędów oraz możliwość podłączenia pakietu wsparcia technicznego. Przeprowadzamy szkolenia z obsługi panelu administracyjnego, dostarczamy szczegółową dokumentację i zawsze jesteśmy gotowi odpowiedzieć na Twoje pytania. Naszym celem jest długoterminowe partnerstwo, dlatego zależy nam na sukcesie Twojego projektu.',
        servicesSeoConclusion: 'Gotowy omówić swój projekt? Skontaktuj się z nami w celu bezpłatnej konsultacji. Przeanalizujemy Twoje potrzeby, zaproponujemy optymalne rozwiązanie i przedstawimy szczegółową wycenę terminów i kosztów realizacji.',
