        pricingCTAButton: 'Uzyskaj wycenę',
        // Pricing Explanation - SEO Text
        pricingExplanationTitle: 'Jak kształtują się koszty tworzenia strony internetowej?',
        pricingSeoText1: 'Koszt stworzenia strony internetowej nie jest stałą kwotą, lecz wynikiem szczegółowej analizy potrzeb Twojego biznesu. Każdy projekt jest unikalny, dlatego do wyceny podchodzimy indywidualnie, uwzględniając specyfikę branży, grupę docelową oraz cele biznesowe klienta. W Web Impuls stawiamy na maksymalną transparentność: zawsze będziesz wiedział, za co płacisz i jaki rezultat otrzymasz.',
        pricingSeoText2: 'Nasze ceny na tworzenie stron internetowych w Europie są konkurencyjne i odpowiadają jakości, którą oferujemy. Współpracujemy z klientami z Polski, Niemiec, Wielkiej Brytanii i innych krajów UE, oferując nowoczesne rozwiązania technologiczne oparte na Next.js, React i TypeScript. Oznacza to szybkie, zoptymalizowane pod SEO strony, które dobrze pozycjonują się w Google i zapewniają wysoką konwersję.',
        pricingSeoHeading1: 'Co wpływa na koszt tworzenia strony?',
        pricingSeoText3: 'Główne czynniki określające cenę to: złożoność projektu graficznego (szablon czy unikalna grafika), liczba podstron i sekcji, wymagana funkcjonalność (formularze, panele klienta, systemy płatności, integracje z CRM), a także terminy realizacji. Na przykład prosta strona landing page z responsywnym designem i podstawową optymalizacją SEO będzie kosztować znacznie mniej niż pełnoprawny sklep internetowy z katalogiem produktów, koszykiem, integracją z bramkami płatności Stripe czy PayU oraz systemem zarządzania zamówieniami.',
        pricingSeoHeading2: 'Dlaczego warto zainwestować w profesjonalną stronę?',
        pricingSeoText4: 'Profesjonalna strona internetowa to nie wydatek, a inwestycja w rozwój biznesu. Dobrze zaprojektowana strona pracuje dla Ciebie 24/7: przyciąga klientów przez organiczne wyniki wyszukiwania, buduje zaufanie do marki, automatyzuje sprzedaż i komunikację. Wykorzystujemy najnowsze technologie web developmentu: renderowanie po stronie serwera dla szybkości ładowania, optymalizację Core Web Vitals dla lepszych pozycji w Google, responsywny design dla wszystkich urządzeń oraz standardy dostępności.',
        pricingSeoHeading3: 'Transparentne ceny bez ukrytych kosztów',
        pricingSeoText5: 'Przed rozpoczęciem pracy otrzymujesz szczegółowy kosztorys z podziałem na etapy: projekt graficzny, kodowanie, programowanie, testowanie, wdrożenie. Cenę ustalamy w umowie, więc nie zmieni się w trakcie realizacji, chyba że nastąpią zmiany w specyfikacji. Płatność zazwyczaj dzieli się na etapy: zaliczka na start, płatność pośrednia po zatwierdzeniu projektu graficznego i rozliczenie końcowe po uruchomieniu projektu.',
        pricingSeoConclusion: 'Gotowy omówić swój projekt? Zostaw zapytanie o bezpłatną konsultację — przeanalizujemy Twoje potrzeby i zaproponujemy optymalne rozwiązanie w ramach Twojego budżetu. Naszym celem jest stworzenie strony, która będzie pracować na wyniki Twojego biznesu.',
        whyChooseUs: 'Dlaczego my?',
        whyChooseUsDesc: 'Łączymy kreatywność, technologie i doświadczenie, aby tworzyć najlepsze rozwiązania',
