        // Landing - Extended content
        spLandingWhatIs: 'What is a Landing Page?',
        spLandingWhatIsText: 'A landing page is a single-page website created with one specific goal: to convert a visitor into a customer. Unlike a regular website, a landing page has no unnecessary elements — every block, every word works toward one goal: getting a lead, sale, or registration.',
        spLandingWhatIsText2: 'It\'s the perfect tool for launching a new product, advertising campaign, collecting contacts, or selling a specific service. A landing page works 24/7, never gets tired, and always says the right things to the right people.',
        spLandingWhyNeed: 'Why do you need a landing page?',
        spLandingWhy1: 'High conversion',
        spLandingWhy1D: 'A landing page converts 5-15% of visitors into customers. A regular website — only 1-3%. This means 5 times more leads with the same advertising budget.',
        spLandingWhy2: 'Focus on one action',
        spLandingWhy2D: 'No distracting elements. The visitor either leaves a request or leaves. Simple choice = more conversions.',
        spLandingWhy3: 'Advertising savings',
        spLandingWhy3D: 'You pay per click in advertising. If the landing page converts better — each click brings more money. ROI multiplies.',
        spLandingWhy4: 'Quick launch',
        spLandingWhy4D: 'A landing page can be launched in 1-2 weeks. It\'s faster than a full website, and you\'ll start getting customers sooner.',
        spLandingForWhom: 'Who is a landing page for?',
