        spWebAppWhatIs: 'What is a web application?',
        spWebAppWhatIsText: 'A web application (SaaS/PWA) is a complex program that runs directly in the browser. Unlike a regular website, it includes authentication, user dashboards, complex logic, integrations with other services, and real-time updates.',
