        // Services SEO Text
        servicesSeoTitle: 'Professional Web Development for Your Business',
        servicesSeoText1: 'Web Impuls is a team of experienced developers and designers specializing in creating modern web solutions for businesses of all sizes. We work with clients from Ukraine, Poland, Germany, and other European countries, providing top-quality services at competitive prices. Our approach is based on a deep understanding of each client\'s needs and the use of cutting-edge web development technologies.',
        servicesSeoText2: 'Every project is a unique opportunity for us to create something special. We don\'t use template solutions — we develop individual designs and functionality that precisely match your business goals. From simple landing pages to complex web applications with payment system integration, CRM, and analytics — we have experience implementing projects of varying complexity.',
        servicesSeoHeading1: 'Why Choose Web Impuls?',
        servicesSeoText3: 'We work exclusively with modern technologies: Next.js 15, React 19, TypeScript, Tailwind CSS, and Prisma ORM. This ensures fast page loading speeds, excellent SEO optimization, and easy ongoing maintenance. Our websites receive high Google PageSpeed Insights scores, which directly affects conversion rates and search rankings. Additionally, we provide full project support — from consultation to launch and ongoing technical maintenance.',
        servicesSeoHeading2: 'Full Development Cycle',
        servicesSeoText4: 'Our services cover the entire web product creation cycle: business requirements analysis, UX/UI design, frontend and backend development, testing, deployment, and ongoing support. We follow Agile methodology, allowing you to see progress at every stage and make adjustments during development. Transparent communication and regular demonstrations are our standard of work.',
        servicesSeoHeading3: 'Quality Guarantee and Support',
        servicesSeoText5: 'After project launch, we don\'t leave you alone. Every client receives a warranty period for free bug fixes and the option to connect a technical support package. We conduct training on working with the admin panel, provide detailed documentation, and are always ready to answer your questions. Our goal is long-term partnership, so we are invested in the success of your project.',
        servicesSeoConclusion: 'Ready to discuss your project? Contact us for a free consultation. We will analyze your needs, propose the optimal solution, and provide a detailed estimate of timelines and development costs.',
        // Pricing Page extras
        pricingViewServices: 'Learn More About Services',
        pricingViewDetails: 'Learn More About Services',
        orderNow: 'Order Now',
        pricingCTATitle: 'Need a custom quote?',
        pricingCTADesc: 'Tell us about your project and get an accurate cost and timeline estimate',
        pricingCTAButton: 'Get a Quote',
        // Pricing Explanation - SEO Text
        pricingExplanationTitle: 'How is website development pricing determined?',
        pricingSeoText1: 'The cost of creating a website is not a fixed number but rather the result of a detailed analysis of your business needs. Every project is unique, which is why we approach pricing individually, taking into account industry specifics, target audience, and client business objectives. At Web Impuls, we strive for maximum transparency: you will always know what you are paying for and what results you will receive.',
        pricingSeoText2: 'Our website development prices in Europe are competitive and match the quality we deliver. We work with clients from Poland, Germany, the UK, and other EU countries, offering modern technological solutions based on Next.js, React, and TypeScript. This means fast, SEO-optimized websites that rank well in Google and ensure high conversion rates.',
        pricingSeoHeading1: 'What factors affect web development costs?',
        pricingSeoText3: 'The main factors determining the price include: design complexity (template or custom), number of pages and sections, required functionality (forms, user dashboards, payment systems, CRM integrations), and project timeline. For example, a simple landing page with responsive design and basic SEO optimization will cost significantly less than a full-featured e-commerce store with product catalog, shopping cart, Stripe or PayPal payment gateway integration, and order management system.',
        pricingSeoHeading2: 'Why invest in a professional website?',
        pricingSeoText4: 'A professional website is not an expense but an investment in business growth. A well-designed website works for you 24/7: attracting customers through organic search, building brand trust, automating sales and communication. We use the latest web development technologies: server-side rendering for fast loading speeds, Core Web Vitals optimization for better Google rankings, responsive design for all devices, and accessibility standards for inclusivity.',
        pricingSeoHeading3: 'Transparent pricing with no hidden fees',
        pricingSeoText5: 'Before we start, you receive a detailed estimate broken down by phases: design, development, programming, testing, and launch. We fix the price in the contract, so it will not change during the project unless there are changes to the specifications. Payment is typically divided into stages: an upfront deposit at the start, an interim payment after design approval, and final settlement after project launch.',
        pricingSeoConclusion: 'Ready to discuss your project? Request a free consultation — we will analyze your needs and propose the optimal solution within your budget. Our goal is to create a website that delivers real results for your business.',
        whyChooseUs: 'Why Choose Us?',
        whyChooseUsDesc: 'We combine creativity, technology and experience to create the best solutions',
        feature1Title: 'Fast',
        feature1Desc: 'Development from 7 days',
        feature2Title: 'Stylish',
