        aboutSeoTitle: 'Warum Web Impuls für Webentwicklung wählen',
        aboutSeoText1: 'Web Impuls ist ein Team erfahrener Entwickler und Designer, das sich auf die Erstellung moderner Websites, Online-Shops und Webanwendungen spezialisiert hat. Wir arbeiten mit Kunden aus der Ukraine, Polen, Deutschland und anderen europäischen Ländern zusammen und bieten einen individuellen Ansatz für jedes Projekt. Unsere Mission ist es, Ihrem Unternehmen zu helfen, sich durch hochwertiges Design, Geschwindigkeit und Benutzerfreundlichkeit von der Konkurrenz abzuheben.',
        aboutSeoText2: 'Wir verwenden die modernsten Technologien: Next.js, React, TypeScript, Tailwind CSS, Node.js und PostgreSQL. Dies ermöglicht es uns, schnelle, sichere und skalierbare Lösungen zu erstellen, die den höchsten Branchenstandards entsprechen. Jedes Projekt wird gründlich getestet und für Suchmaschinen (SEO) optimiert, was hohe Platzierungen bei Google und anderen Suchmaschinen garantiert.',
        aboutSeoText3: 'Unsere über 5-jährige Erfahrung in der Webentwicklung, mehr als 150 erfolgreich abgeschlossene Projekte und über 50 zufriedene Kunden sind Ihre Qualitätsgarantie. Wir bieten einen vollständigen Service: von Konzeptentwicklung und Design bis hin zu Launch, technischem Support und Promotion. Bestellen Sie eine kostenlose Beratung und erfahren Sie, wie wir Ihrem Unternehmen helfen können, online zu wachsen.',
