        // Landing - Extended content
        spLandingWhatIs: 'Was ist eine Landing Page?',
        spLandingWhatIsText: 'Eine Landing Page ist eine einseitige Website, die mit einem konkreten Ziel erstellt wurde: einen Besucher in einen Kunden zu verwandeln. Anders als eine normale Website hat eine Landing Page keine überflüssigen Elemente — jeder Block, jedes Wort arbeitet auf ein Ziel hin: einen Lead, Verkauf oder eine Registrierung zu erhalten.',
        spLandingWhatIsText2: 'Es ist das perfekte Werkzeug für den Start eines neuen Produkts, einer Werbekampagne, zum Sammeln von Kontakten oder zum Verkauf einer bestimmten Dienstleistung. Eine Landing Page arbeitet 24/7, wird nie müde und sagt immer die richtigen Dinge zu den richtigen Leuten.',
