        spLandingWhy2: 'Fokus auf eine Aktion',
        spLandingWhy2D: 'Keine ablenkenden Elemente. Der Besucher hinterlässt entweder eine Anfrage oder geht. Einfache Wahl = mehr Konversionen.',
        spLandingWhy3: 'Werbeersparnis',
        spLandingWhy3D: 'Sie zahlen pro Klick in der Werbung. Wenn die Landing Page besser konvertiert — bringt jeder Klick mehr Geld. ROI vervielfacht sich.',
        spLandingWhy4: 'Schneller Start',
        spLandingWhy4D: 'Eine Landing Page kann in 1-2 Wochen gestartet werden. Das ist schneller als eine vollständige Website, und Sie beginnen früher, Kunden zu gewinnen.',
