        servicesCtaTitle: 'Nicht sicher, welche Dienstleistung Sie wählen sollen?',
        servicesCtaDesc: 'Erzählen Sie uns von Ihrem Projekt und wir helfen Ihnen, die beste Lösung zu finden',
        getConsultation: 'Beratung anfordern',
        viewPricing: 'Preise ansehen',
        // Services SEO Text
        servicesSeoTitle: 'Professionelle Webentwicklung für Ihr Unternehmen',
        servicesSeoText1: 'Web Impuls ist ein Team erfahrener Entwickler und Designer, das sich auf die Erstellung moderner Weblösungen für Unternehmen jeder Größe spezialisiert hat. Wir arbeiten mit Kunden aus der Ukraine, Polen, Deutschland und anderen europäischen Ländern zusammen und bieten erstklassige Dienstleistungen zu wettbewerbsfähigen Preisen. Unser Ansatz basiert auf einem tiefen Verständnis der Bedürfnisse jedes Kunden und dem Einsatz modernster Webentwicklungstechnologien.',
        servicesSeoText2: 'Jedes Projekt ist für uns eine einzigartige Gelegenheit, etwas Besonderes zu schaffen. Wir verwenden keine Vorlagenlösungen — wir entwickeln individuelles Design und Funktionalität, die genau Ihren Geschäftszielen entsprechen. Von einfachen Landingpages bis hin zu komplexen Webanwendungen mit Integration von Zahlungssystemen, CRM und Analytik — wir haben Erfahrung in der Umsetzung von Projekten unterschiedlicher Komplexität.',
        servicesSeoHeading1: 'Warum Web Impuls wählen?',
        servicesSeoText3: 'Wir arbeiten ausschließlich mit modernen Technologien: Next.js 15, React 19, TypeScript, Tailwind CSS und Prisma ORM. Dies gewährleistet schnelle Ladezeiten, exzellente SEO-Optimierung und einfache laufende Wartung. Unsere Websites erhalten hohe Google PageSpeed Insights-Bewertungen, was sich direkt auf Konversionsraten und Suchmaschinen-Rankings auswirkt. Darüber hinaus bieten wir vollständige Projektunterstützung — von der Beratung über den Launch bis hin zur laufenden technischen Wartung.',
        servicesSeoHeading2: 'Vollständiger Entwicklungszyklus',
        servicesSeoText4: 'Unsere Dienstleistungen decken den gesamten Zyklus der Webprodukt-Erstellung ab: Geschäftsanforderungsanalyse, UX/UI-Design, Frontend- und Backend-Entwicklung, Testing, Deployment und laufender Support. Wir arbeiten nach der Agile-Methodik, sodass Sie den Fortschritt in jeder Phase verfolgen und während der Entwicklung Anpassungen vornehmen können. Transparente Kommunikation und regelmäßige Demonstrationen sind unser Arbeitsstandard.',
        servicesSeoHeading3: 'Qualitätsgarantie und Support',
        servicesSeoText5: 'Nach dem Projektstart lassen wir Sie nicht allein. Jeder Kunde erhält eine Garantiezeit für kostenlose Fehlerbehebungen sowie die Möglichkeit, ein technisches Support-Paket anzuschließen. Wir führen Schulungen zur Arbeit mit dem Admin-Panel durch, stellen detaillierte Dokumentation bereit und sind immer bereit, Ihre Fragen zu beantworten. Unser Ziel ist eine langfristige Partnerschaft, daher sind wir am Erfolg Ihres Projekts interessiert.',
        servicesSeoConclusion: 'Bereit, Ihr Projekt zu besprechen? Kontaktieren Sie uns für eine kostenlose Beratung. Wir analysieren Ihre Anforderungen, schlagen die optimale Lösung vor und erstellen eine detaillierte Schätzung der Zeitrahmen und Entwicklungskosten.',
        // Pricing Page extras
        pricingViewServices: 'Mehr über Dienstleistungen',
        pricingViewDetails: 'Mehr über Dienstleistungen',
        orderNow: 'Jetzt bestellen',
        pricingCTATitle: 'Benötigen Sie ein individuelles Angebot?',
        pricingCTADesc: 'Erzählen Sie uns von Ihrem Projekt und erhalten Sie eine genaue Kosten- und Zeitschätzung',
        pricingCTAButton: 'Angebot anfordern',
        // Pricing Explanation - SEO Text
        pricingExplanationTitle: 'Wie werden die Kosten für die Website-Entwicklung berechnet?',
        pricingSeoText1: 'Die Kosten für die Erstellung einer Website sind keine feste Zahl, sondern das Ergebnis einer detaillierten Analyse Ihrer Geschäftsanforderungen. Jedes Projekt ist einzigartig, weshalb wir die Preisgestaltung individuell angehen und dabei Branchenspezifika, Zielgruppe und Geschäftsziele des Kunden berücksichtigen. Bei Web Impuls streben wir nach maximaler Transparenz: Sie wissen immer, wofür Sie bezahlen und welche Ergebnisse Sie erhalten.',
        pricingSeoText2: 'Unsere Preise für die Website-Entwicklung in Europa sind wettbewerbsfähig und entsprechen der Qualität, die wir liefern. Wir arbeiten mit Kunden aus Polen, Deutschland, Großbritannien und anderen EU-Ländern zusammen und bieten moderne technologische Lösungen auf Basis von Next.js, React und TypeScript. Das bedeutet schnelle, SEO-optimierte Websites, die gut bei Google ranken und hohe Konversionsraten gewährleisten.',
        pricingSeoHeading1: 'Welche Faktoren beeinflussen die Webentwicklungskosten?',
        pricingSeoText3: 'Die Hauptfaktoren, die den Preis bestimmen, sind: Designkomplexität (Vorlage oder individuell), Anzahl der Seiten und Abschnitte, erforderliche Funktionalität (Formulare, Benutzer-Dashboards, Zahlungssysteme, CRM-Integrationen) sowie der Projektzeitrahmen. Beispielsweise kostet eine einfache Landing Page mit responsivem Design und grundlegender SEO-Optimierung deutlich weniger als ein vollwertiger Online-Shop mit Produktkatalog, Warenkorb, Stripe- oder PayPal-Zahlungsintegration und Bestellverwaltungssystem.',
        pricingSeoHeading2: 'Warum in eine professionelle Website investieren?',
        pricingSeoText4: 'Eine professionelle Website ist keine Ausgabe, sondern eine Investition in das Geschäftswachstum. Eine gut gestaltete Website arbeitet 24/7 für Sie: Sie zieht Kunden über organische Suche an, baut Markenvertrauen auf und automatisiert Vertrieb und Kommunikation. Wir nutzen die neuesten Webentwicklungstechnologien: serverseitiges Rendering für schnelle Ladezeiten, Core Web Vitals-Optimierung für bessere Google-Rankings, responsives Design für alle Geräte und Barrierefreiheitsstandards für Inklusion.',
        pricingSeoHeading3: 'Transparente Preise ohne versteckte Gebühren',
        pricingSeoText5: 'Bevor wir beginnen, erhalten Sie einen detaillierten Kostenvoranschlag, aufgeschlüsselt nach Phasen: Design, Entwicklung, Programmierung, Testing und Launch. Wir fixieren den Preis im Vertrag, sodass er sich während des Projekts nicht ändert, es sei denn, es gibt Änderungen an den Spezifikationen. Die Zahlung wird typischerweise in Phasen aufgeteilt: eine Anzahlung zu Beginn, eine Zwischenzahlung nach Designfreigabe und die Endabrechnung nach Projektstart.',
        pricingSeoConclusion: 'Bereit, Ihr Projekt zu besprechen? Fordern Sie eine kostenlose Beratung an — wir analysieren Ihre Anforderungen und schlagen die optimale Lösung für Ihr Budget vor. Unser Ziel ist es, eine Website zu erstellen, die echte Ergebnisse für Ihr Unternehmen liefert.',
        whyChooseUs: 'Warum wir?',
        whyChooseUsDesc: 'Wir verbinden Kreativität, Technologie und Erfahrung, um die besten Lösungen zu schaffen',
